// === Tab: mySketch ===
// 普通にfractすると整数1ごとにグリッドができる。
// これを2本の一次独立なベクトルを使ってやってみるわけ。
// 基本は(0, 1)と(1, 0)でやってるけど・・内積取って座標を算出する感じ。

// シンプレックスノイズよくわかんなかったから
// こんなもんかなーって独自実装しちゃった。
// でもあれとは全然違うでしょうね。たぶん。

// とりあえずgetGridの計算部分を簡略化してみる

// で、さらにfbmぶちこんでみる

// absにして割合を変化させてみる

// fbmで縁取りを作ってみたいね

let myShader;
let properFrameCount = 0;

let vs =
"precision mediump float;" +
"attribute vec3 aPosition;" +
"void main(void){" +
"  gl_Position = vec4(aPosition, 1.0);" +
"}";

let fs =
"precision mediump float;" +
"uniform vec2 u_resolution;" +
"uniform vec2 u_mouse;" +
"uniform float u_time;" +
"const float pi = 3.14159;" +
"const vec2 r_vector = vec2(12.9898, 78.233);" +
"const float r_coeff = 43758.5453123;" +
// snoise用のベクトル
"const vec2 c1 = vec2(1.0, 0.5773502);" +
"const vec2 c2 = vec2(0.0, 1.1547005);" +
// 色関連
"const vec3 groundColor = vec3(0.627, 0.392, 0.263);" + // 茶色っぽい
"const vec3 seaColor = vec3(0.286, 0.325, 0.811);" + // 青っぽい
"const vec3 forestColor = vec3(0.106, 0.552, 0.239);" + // 緑っぽい？
"const vec2 ratio = vec2(0.545, 0.59);" +
// fbm関連
"const int octaves = 4;" +
// 2Dランダムベクトル(-1.0～1.0)
"vec2 random2(vec2 st){" +
"  vec2 v = vec2(0.0);" +
"  v.x = sin(dot(st, vec2(127.1, 311.7))) * r_coeff;" +
"  v.y = sin(dot(st, vec2(269.5, 183.3))) * r_coeff;" +
"  return -1.0 + 2.0 * fract(v);" + // -1.0～1.0に正規化
"}" +
// hsbで書かれた(0.0～1.0)の数値vec3をrgbに変換する魔法のコード
"vec3 getHSB(float r, float g, float b){" +
"    vec3 c = vec3(r, g, b);" +
"    vec3 rgb = clamp(abs(mod(c.x * 6.0 + vec3(0.0, 4.0, 2.0), 6.0) - 3.0) - 1.0, 0.0, 1.0);" +
"    rgb = rgb * rgb * (3.0 - 2.0 * rgb);" +
"    return c.z * mix(vec3(1.0), rgb, c.y);" +
"}" +
// e1, e2は単位ベクトルでなくていいけど一次独立でないと('ω'乂)ﾀﾞﾒｰ
// 三角形を細かくするために係数を大小比較して・・
// 多分これ直線y=xで点対称（中点中心の180°回転）してる。
// 具体的には1-x, 1-yで取り替えてるっぽい。
// 整理して単なる内積にした
"float snoise(vec2 p){" +
"  vec2 v = vec2(dot(c1, p), dot(c2, p));" +
"  vec2 f = fract(v);" +
"  vec2 i = floor(v);" +
"  vec2 x0, x1, x2;" +
"  vec3 w;" +
"  if(f.x > f.y){" +
"    x0 = i; x1 = i + vec2(1.0, 0.0); x2 = i + vec2(1.0, 1.0);" +
"    w.x = 1.0 - f.x; w.y = f.x - f.y; w.z = f.y;" +
"  }else{" +
"    x0 = i + vec2(1.0, 1.0); x1 = i + vec2(0.0, 1.0); x2 = i;" +
"    w.x = f.x; w.y = f.y - f.x; w.z = 1.0 - f.y;" +
"  }" +
"  vec3 value;" +
"  value.x = dot(v - x0, random2(x0));" +
"  value.y = dot(v - x1, random2(x1));" +
"  value.z = dot(v - x2, random2(x2));" +
"  w = w * w * (3.0 - 2.0 * w);" +
"  return dot(w, value);" +
"}" +
// fbmやってみる
// スタンダードにamplitudeが0.5, lacunarityが2.0, gainが0.4でいってみる
"float fbm(vec2 st, float amplitude, float lacunarity, float gain){" +
"  float value = 0.0;" +
"  for(int i = 0; i < octaves; i++){" +
"    value += amplitude * snoise(st);" +
"    st *= lacunarity;" +
"    amplitude *= gain;" +
"  }" +
"  return value;" +
"}" +
// メインコード
"void main(void){" +
"  vec2 st = (gl_FragCoord.xy - u_resolution) / min(u_resolution.x, u_resolution.y);" +
"  float r = length(st);" +
"  float theta = atan(st.y, st.x);" +
// fbmで円の縁取りを作るんだけど、サンプルとなる円を平面上で平行移動させるわけね。
// 半径はもう4.0で固定でいいです
// 中心の移動速度だけ適当に決める感じ
"  float sampleRadius = 4.0;" +
"  vec2 sampleCenter = vec2(0.3, 0.4) * u_time;" +
"  float n = fbm(sampleRadius * (vec2(cos(theta), sin(theta)) + sampleCenter), 0.5, 2.0, 0.4);" +
"  float ar = 0.5 + 0.4 * n;" +
"  float hue = 1.0;" +
"  float sat = 1.0;" +
"  float bl = 1.0;" +
"  if(r < ar){" +
"    hue = 0.66;" +
"    bl = 0.3 * r / ar;" + // めちゃ暗くする
"  }else{" +
"    hue = mod(0.5 + u_time * 0.05, 1.0);" + // 色はいつものように周期変化
"    bl = ar / r;" + // 外側ほど暗くなるように調整
"  }" +
"  gl_FragColor = vec4(getHSB(hue, sat, bl), 1.0);" +
"}";

let inc = 1;
let lapse = 0;    // mouse timer

function setup(){
  createCanvas(1112, 834, WEBGL);
  myShader = createShader(vs, fs);
	background(0);
  shader(myShader);
  //noLoop();
}

function draw(){
  myShader.setUniform("u_resolution", [width, height]);
  myShader.setUniform("u_mouse", [(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))]);
  myShader.setUniform("u_time", properFrameCount / 60);
  quad(-1, -1, -1, 1, 1, 1, 1, -1);
  properFrameCount += inc;
	if (properFrameCount > 700 || properFrameCount < 0){
		inc = -inc;
  }
}

function mousePressed(){
// prevents mouse press from registering twice
  if (frameCount - lapse > 15){
    save('pix.jpg');
    lapse = frameCount;
  }
}

